hazard['id'].'/estado')) ?>"><?= csrf_field() ?><input type="hidden" name="estado" value="<?= $hazard['estado']==='Activo'?'Controlado':'Activo' ?>"><span class="badge <?= status_class($hazard['estado']) ?>"><?= e($hazard['estado']) ?></span><button class="mt-2 block text-[10px] font-medium text-blue-600"><?= $hazard['estado']==='Activo'?'Marcar controlado':'Reactivar' ?></button></form><?php if($hazard['proxima_revision']&&$hazard['proxima_revision']<date('Y-m-d')): ?><span class="badge badge-red mt-2">Revisión vencida</span><?php endif; ?></td><td><div class="flex min-w-28 flex-col items-start gap-2"><a href="<?= e(url('/matriz-ipevr/'.$hazard['id'])) ?>" class="text-[11px] font-medium text-blue-600">Abrir ficha y controles</a><a href="<?= e(url('/evidencias?vinculo='.rawurlencode('peligro:'.$hazard['id']).'#cargar')) ?>" class="text-[11px] font-medium text-blue-600">Soporte</a><?php if(!$hazard['verificado_at']): ?><form method="post" action="<?= e(url('/matriz-ipevr/'.$hazard['id'].'/verificar')) ?>"><?= csrf_field() ?><button class="text-left text-[11px] font-medium text-blue-600">Verificar evaluación</button></form><?php else: ?><span class="text-[10px] text-emerald-600">Verificada <?= format_date($hazard['verificado_at']) ?></span><?php endif; ?><a href="<?= e(url('/matriz-ipevr/'.$hazard['id'].'/editar')) ?>" class="text-[11px] font-medium text-blue-600">Editar</a><form method="post" action="<?= e(url('/matriz-ipevr/'.$hazard['id'].'/eliminar')) ?>" data-confirm="¿Eliminar este peligro y sus controles asociados?"><?= csrf_field() ?><button class="text-left text-[11px] font-medium text-rose-600">Eliminar</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
