bel><select name="nivel_consecuencia" class="input" data-risk-nc><option value="">Sin valorar</option><?php foreach([10,25,60,100] as $value): ?><option value="<?= $value ?>"<?= selected(old('nivel_consecuencia'),$value) ?>><?= $value ?></option><?php endforeach; ?></select></div><div><label class="label">Nivel manual alternativo</label><select name="nivel_riesgo" class="input" data-risk-fallback><?php foreach(['Bajo','Medio','Alto','Critico'] as $level): ?><option<?= selected(old('nivel_riesgo','Medio'),$level) ?>><?= $level ?></option><?php endforeach; ?></select></div></div><div class="mt-4 rounded-xl bg-white p-3 text-xs">Resultado orientativo: <strong data-risk-result>Sin valores completos</strong></div></div><div class="mt-5 flex justify-end"><button class="btn-primary">Guardar en la IPEVR</button></div></form></details>
